// AXI4-Lite Read FSM State Machine
localparam IDLE  = 2'b00;
localparam READ  = 2'b01;
localparam WAIT  = 2'b10;

always @(posedge S_AXI_ACLK) begin
    if (!S_AXI_ARESETN) begin
        state <= IDLE;
        S_AXI_ARREADY <= 1'b0;
        S_AXI_RVALID  <= 1'b0;
    end else begin
        case (state)
            IDLE: begin
                if (S_AXI_ARVALID) begin
                    S_AXI_ARREADY <= 1'b1;
                    state <= READ;
                end
            end
            READ: begin
                S_AXI_ARREADY <= 1'b0;
                S_AXI_RVALID  <= 1'b1;
                state <= WAIT;
            end
            WAIT: begin
                if (S_AXI_RREADY) begin
                    S_AXI_RVALID <= 1'b0;
                    state <= IDLE;
                end
            end
        endcase
    end
end
